function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => v !== 0 && v !== 1)) return 'Every value of nums is 0 or 1.';
  if (!Number.isInteger(k) || k < 0 || k > nums.length) return 'k is between 0 and nums.length.';
  return null;
}

