function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 10);
  const mode = rand();
  if (mode < 0.5) {
    // Build an array whose gaps are at least k most of the time, so true answers are common.
    const k = Math.floor(rand() * (size === 'large' ? 40 : 4));
    const nums = new Array(n).fill(0);
    let i = Math.floor(rand() * 3);
    while (i < n) {
      nums[i] = 1;
      i += k + 1 + Math.floor(rand() * 3);
    }
    // Sometimes break one gap so the answer flips to false.
    if (rand() < 0.4) {
      const pos = Math.floor(rand() * n);
      nums[pos] = 1;
    }
    return [nums, Math.min(k, n)];
  }
  const density = rand();
  const nums = Array.from({ length: n }, () => (rand() < density ? 1 : 0));
  const k = Math.floor(rand() * (Math.min(n, size === 'large' ? 50 : n) + 1));
  return [nums, k];
}
